// Convierte { ubicaciones: [...] } en un item de n8n por cada ubicación a snapshotear
const data = $input.first().json;
if (!data.ubicaciones || data.ubicaciones.length === 0) {
  return [];
}
return data.ubicaciones.map(u => ({ json: u }));

// Por cada ubicación: pide clima (Weather API) + oleaje (Marine API, solo aporta
// dato si es punto costero — en tierra viene null y no rompe nada, igual que en
// la vista Django "naval"), arma UNA fila por variable según el sector, y
// descarta valores null/undefined para no ensuciar BigQuery.
const items = $input.all();
const resultados = [];

for (const item of items) {
  const { lat, lon, sector, nombre } = item.json;

  let clima = {};
  try {
    clima = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.open-meteo.com/v1/forecast',
      qs: {
        latitude: lat,
        longitude: lon,
        current: 'temperature_2m,precipitation,relative_humidity_2m,wind_speed_10m,wind_gusts_10m,cloud_cover,cape,shortwave_radiation,pressure_msl',
        timezone: 'auto',
      },
      json: true,
    });
  } catch (e) { clima = { current: {} }; }

  let marine = {};
  try {
    marine = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://marine-api.open-meteo.com/v1/marine',
      qs: { latitude: lat, longitude: lon, current: 'wave_height,wave_period', timezone: 'auto' },
      json: true,
    });
  } catch (e) { marine = { current: {} }; }

  const c = clima.current || {};
  const m = marine.current || {};
  const timestamp = new Date().toISOString();

  // Mismo criterio de variables/unidades que las vistas Django estadisticas_<sector>
  const MAPA = {
    agro: {
      precipitacion: c.precipitation,
      temperatura: c.temperature_2m,
      humedad: c.relative_humidity_2m,
      viento: c.wind_speed_10m,
    },
    naval: {
      olas: m.wave_height,
      periodo_ola: m.wave_period,
      viento: c.wind_speed_10m != null ? +(c.wind_speed_10m * 0.539957).toFixed(2) : null,
      temperatura: c.temperature_2m,
    },
    aereo: {
      temperatura: c.temperature_2m,
      viento: c.wind_speed_10m != null ? +(c.wind_speed_10m / 1.852).toFixed(2) : null,
      rafagas: c.wind_gusts_10m != null ? +(c.wind_gusts_10m / 1.852).toFixed(2) : null,
      nubosidad: c.cloud_cover,
      cape: c.cape,
    },
    energia: {
      radiacion: c.shortwave_radiation,
      viento: c.wind_speed_10m != null ? +(c.wind_speed_10m / 3.6).toFixed(2) : null,
      temperatura: c.temperature_2m,
      presion: c.pressure_msl,
    },
  };

  const variables = MAPA[sector] || {};
  for (const [variable, valor] of Object.entries(variables)) {
    if (valor === null || valor === undefined || Number.isNaN(valor)) continue;
    resultados.push({
      json: { timestamp, sector, lat, lon, nombre_ubicacion: nombre, variable, valor },
    });
  }
}

return resultados;

