INSERT INTO `proyecto-bi-488218.datos_clima.snapshots_historicos`
(timestamp, sector, lat, lon, nombre_ubicacion, variable, valor)
VALUES (
  COALESCE(SAFE.PARSE_TIMESTAMP('%Y-%m-%dT%H:%M:%E*SZ', @timestamp), CURRENT_TIMESTAMP()),
  @sector,
  SAFE_CAST(@lat AS FLOAT64),
  SAFE_CAST(@lon AS FLOAT64),
  @nombre_ubicacion,
  @variable,
  SAFE_CAST(@valor AS FLOAT64)
);
